"""Stdlib-only numeric trace for IdeaSpark Phase 2.3."""
from __future__ import annotations
import json, math, statistics, sys

def iqr(values):
    ordered=sorted(values); half=len(ordered)//2
    return statistics.median(ordered[half:])-statistics.median(ordered[:half])

def residual_norm(vector,basis):
    projected=[0.0]*len(vector)
    for axis in basis:
        coefficient=sum(x*y for x,y in zip(vector,axis))
        projected=[p+coefficient*a for p,a in zip(projected,axis)]
    return math.sqrt(sum((x-p)**2 for x,p in zip(vector,projected)))
term_samples={'R_V':[1.,2.,3.,4.],'R_q':[2.,2.,2.,2.],'R_T':[10.,12.,14.,16.],'R_phi':[.1,.2,.4,.8]}
scales={n:(raw if (raw:=iqr(xs)) else sys.float_info.epsilon) for n,xs in term_samples.items()}
validation={'switch':[.2,.4],'topology':[.1,.3],'energy':[.3,.5],'event_order':[0.,1.]}
means={n:statistics.fmean(xs) for n,xs in validation.items()}
j_val=statistics.fmean(means[n] for n in ('switch','topology','energy'))
responses={'b1':[3.,0.,0.],'b2':[0.,2.,0.],'b3':[0.,0.,1.],'b4':[1.,1.,0.]}
sensitivities={'b1':.4,'b2':.3,'b3':.2,'b4':.5}
basis_r1=[[1.,0.,0.]]; basis_r2=basis_r1+[[0.,1.,0.]]
deltas_r1={b:residual_norm(v,basis_r1) for b,v in responses.items()}; deltas_r2={b:residual_norm(v,basis_r2) for b,v in responses.items()}
scores_r1={b:sensitivities[b]*deltas_r1[b] for b in responses}; scores_r2={b:sensitivities[b]*deltas_r2[b] for b in responses}
delta=.25; gradient_gate=1.; l_gate=0.; actual_removal_change=1.; written_bound=abs(gradient_gate)*delta+(l_gate/2)*delta**2
packet_benefits=[0.,.6,.2,.5]; mechanism_error=1.-packet_benefits[1]; naive_error=1.-sum(.25*x for x in packet_benefits); mechanism_error_r2=1.-packet_benefits[2]
result={'scales':scales,'validation_component_means':means,'J_val_three_component_scalar':j_val,'delta_if_r_bulk_1':deltas_r1,'delta_if_r_bulk_2':deltas_r2,'I_if_r_bulk_1':scores_r1,'I_if_r_bulk_2':scores_r2,'rank_dependent_order_r1':sorted(scores_r1,key=scores_r1.get,reverse=True),'rank_dependent_order_r2':sorted(scores_r2,key=scores_r2.get,reverse=True),'bound_counterexample':{'J(g)':'g','delta_b':delta,'gradient_wrt_gate':gradient_gate,'L_g':l_gate,'actual_removal_change':actual_removal_change,'written_B_R':written_bound,'gate_coordinate_Taylor_bound':1.,'written_bound_violated':actual_removal_change>written_bound},'degenerate_probes':{'empty_packets':'no cumulative curve; no knee; declared stop branch','k_zero_local_heads':'hybrid collapses to f_bulk; no routed minority can be tested','all_identical_scores':'cumulative curve is linear; no minority-forming curvature','tied_max_curvature':'selection is non-unique without a stated tie rule','single_packet':'no interior curvature point; declared no-knee stop'},'naive_same_budget':{'head_capacity':1.,'mechanism_allocation_r1':[0.,1.,0.,0.],'mechanism_allocation_r2':[0.,0.,1.,0.],'uniform_naive_allocation':[.25,.25,.25,.25],'mechanism_error_r1':mechanism_error,'mechanism_error_r2':mechanism_error_r2,'naive_error':naive_error,'error_difference_naive_minus_mechanism_r1':naive_error-mechanism_error,'error_difference_naive_minus_mechanism_r2':naive_error-mechanism_error_r2}}
print(json.dumps(result,indent=2,sort_keys=True))
